// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 1);
    }
    function testFuzz_property(uint256 amount, address payable receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // sendTo must never succeed when it asks to move more wei than c holds.
        assertTrue(!(ok && amount > 1));
    }
}
